"""zoo_month: A Month at the Zoo on Extella (simulator + plan expert in one file)."""
import json, math


def zoo_month(mode="evening", place="waterfront", team="mid", scenario="flu", seed=1, decisions=None, plan=None):
    """A Month at the Zoo on Extella (world ny2, the one on extella.dev/zoo).

    mode="evening": replays `decisions` (the month so far, [[evening, decision], ...]) and returns the current
    evening: what the manager sees, the open cards in words, and the expert's estimates for a normal plan.
    With `plan` (stock, staff: lean|normal|safe; optional shows 0-2, price -50..100, free_wed true|false,
    choices {card_id: option}; whatever is left out is chosen by the expert, as in the recorded months) the expert
    zoo_game_plan turns the plan into the exact decision (thaw, orders, shifts, hires, price), the day is played and
    the answer carries the updated `decisions` and what happened.
    mode="check": replays a whole month log and returns the score (for the leaderboard).
    Worlds: place park|waterfront|subway, team small|mid|large, scenario heat|spring|flu.
    """
    log = _clean(decisions)
    settings = {"place": place, "team": team, "scenario": scenario}
    if mode == "check":
        try:
            r = replay(int(seed), settings, [(d, dec) for d, dec in log], "ny2")
        except ValueError as e:
            return {"status": "error", "error": str(e)}
        return {"status": "success", "settings": dict(settings, seed=int(seed)), "score": r["score"], "parts": r["parts"], "counts": r["counts"]}
    g = Game(int(seed), place, team, scenario, "ny2")
    for d, dec in log:
        if d != g.t:
            raise ValueError("decisions: one decision per evening, evenings 0, 1, 2, ... in order")
        g.decide(dec); g.step()
    if g.done():
        return {"finished": True, "score": g.score(), "decisions": log}
    W = _public_world()
    obs = g.observe()
    cards = [_card_en(c) for c in obs["cards"]]
    if not plan:
        res = zoo_game_plan(obs, dict(_EXPERT_PICKS, stock="normal", staff="normal"), W)
        return {"evening": g.t, "observation": obs, "cards_text": cards, "estimates_for_normal_plan": res["estimates"],
                "warnings": res["warnings"], "decisions": log}
    full = _full_plan(plan)
    res = zoo_game_plan(obs, full, W)
    rej, _ = g.check(res["decision"])
    day = g.t
    g.decide(res["decision"]); g.step()
    log.append([day, res["decision"]])
    out = {"evening": day, "plan": full, "decision": res["decision"], "estimates": res["estimates"], "warnings": res["warnings"],
           "rejections": rej, "yesterday": g.last_report, "score_so_far": g.score()["score"], "decisions": log}
    if g.done():
        out["finished"] = True; out["score"] = g.score()
    return out


